import{f as t,o as a,c as i,aj as e}from"./chunks/framework.CJTJR_Xv.js";const k=JSON.parse('{"title":"HTTPS 的证书配置","description":"记录一下对 HTTPS 的证书配置的来时路","frontmatter":{"title":"HTTPS 的证书配置","description":"记录一下对 HTTPS 的证书配置的来时路","tags":["HTTPS","证书"],"date":"2025-11-24T00:00:00.000Z","author":"沃以"},"headers":[],"relativePath":"building/HTTPS的证书配置.md","filePath":"building/HTTPS的证书配置.md","lastUpdated":1788599939000}'),n={name:"building/HTTPS的证书配置.md"};function l(p,s,h,o,r,d){return a(),i("div",null,s[0]||(s[0]=[e(`<h1 id="从腾讯云免费证书迁移到-certbot-一次-https-自动化之旅" tabindex="-1">从腾讯云免费证书迁移到 Certbot：一次 HTTPS 自动化之旅 <a class="header-anchor" href="#从腾讯云免费证书迁移到-certbot-一次-https-自动化之旅" aria-label="Permalink to &quot;从腾讯云免费证书迁移到 Certbot：一次 HTTPS 自动化之旅&quot;">​</a></h1><p>https 在我印象中，一直是一个收费昂贵的解决方案，阿里云上动辄300 元/年，对于我来说，这太贵了。在24年的时候，和室友一起参加了 中国大学生计算机设计大赛。为了能在公网访问我们的项目，我在腾讯云上申请了免费的 SSL 证书，后来用于我的个人博客网站。</p><p>虽然是手动的，配置nginx 在windows服务器上使用，但总算是实现了 https。</p><blockquote><p>值得一提的是，这个大学生计算机设计大赛中南赛区的评判中，根本没有访问我们的网站就随便给了个分数，太让我生气了...🤒</p></blockquote><p>但服务器本身的成本昂贵，2h2g 腾讯云一年要 99 元，还是在我承受的范围内。在2h2g的服务器上使用windows系统，实在是太吃力了。后来我把服务器换成了 ubuntu 系统，重新配置了 Nginx。</p><p>但你知道的 linux 的一切操作都是命令行，频繁的 shell 命令行操作实在是太繁琐了，与此同时，在google的推进下，https证书的有效期被缩短到了90天。 每次证书到期前，我都得登录腾讯云控制台，重新下载、上传、重载 Nginx 服务。</p><p>于是，在25年重启博客网站的途中，与其再试图获取腾讯云接口，再写脚本来实现自动化，不如彻底迁移到 <strong>Certbot + Let&#39;s Encrypt</strong> 方案，实现真正的一键部署、自动续期。</p><p>这个博客就是记录一下 Certbot 的使用方法，以及如何实现自动化。</p><h2 id="迁移前准备" tabindex="-1">迁移前准备 <a class="header-anchor" href="#迁移前准备" aria-label="Permalink to &quot;迁移前准备&quot;">​</a></h2><p>我的服务器环境：</p><ul><li>Ubuntu 22.04 LTS</li><li>Nginx 作为反向代理</li><li>域名已正确解析到服务器公网 IP</li><li>80 和 443 端口已在腾讯云安全组开放</li></ul><p>确保站点可通过 <code>http://your-domain/.well-known/acme-challenge/</code> 临时路径被外网访问（Certbot 验证域名所有权必需）。</p><h2 id="安装-certbot" tabindex="-1">安装 Certbot <a class="header-anchor" href="#安装-certbot" aria-label="Permalink to &quot;安装 Certbot&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certbot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-certbot-nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><h2 id="获取并自动配置证书" tabindex="-1">获取并自动配置证书 <a class="header-anchor" href="#获取并自动配置证书" aria-label="Permalink to &quot;获取并自动配置证书&quot;">​</a></h2><p>执行以下命令，Certbot 会自动检测 Nginx 配置中的 <code>server_name</code>，并完成证书申请与 HTTPS 配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certbot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果这里你像我一样，同时配置了 domain.com 和 &lt;www.domain.com&gt; 两个域名，请确保两个域名都已经正确解析到服务器 IP，否则会申请失败。</p></div><p>过程中会提示：</p><ul><li>输入邮箱（用于证书到期提醒）</li><li>同意 Let&#39;s Encrypt 服务条款</li><li>是否将 HTTP 请求自动重定向到 HTTPS（强烈建议选 <strong>2：自动重定向</strong>）</li></ul><p>完成后，Nginx 配置会自动更新，新增 SSL 相关指令，并设置 301 重定向。</p><h2 id="验证自动续期" tabindex="-1">验证自动续期 <a class="header-anchor" href="#验证自动续期" aria-label="Permalink to &quot;验证自动续期&quot;">​</a></h2><p>Let&#39;s Encrypt 证书有效期为 <strong>90 天</strong>，但 Certbot 会通过 systemd timer 或 cron 自动续期。可手动测试续期流程：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certbot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renew</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>如果输出显示成功，说明自动续期机制已正常工作。</p><h2 id="总之" tabindex="-1">总之 <a class="header-anchor" href="#总之" aria-label="Permalink to &quot;总之&quot;">​</a></h2><p>作为开发者，我越来越体会到：<strong>“能自动化的绝不手动，能开源的绝不闭源”</strong>。这一次小小的迁移，也让我少了不少的麻烦。</p><blockquote><p>2025 年 11 月 24 日 · 于武汉 · 沃以</p></blockquote>`,28)]))}const g=t(n,[["render",l]]);export{k as __pageData,g as default};
